    setMessages(updated);
    setLoading(true);
    const history = updated.filter(m=>m.role!=="system"&&m.source!=="system");
    const result = await processQuery(msg, learnedDict, history, (d, key) => {
      setLearnedDict(d);
      setLearned(Object.keys(d).length);
    });
    setMessages(prev => [...prev, {role:"assistant", content: result.answer || "", source: result.source, law: result.law, learned: result.learned, emotionColor: result.emotionColor, emotion: result.emotion}]);
